create table if not exists public.categories (id bigint generated by default as identity primary key, alias varchar(120) not null unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.tags (id bigint generated by default as identity primary key, alias varchar(120) not null unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.category_translations (id bigint generated by default as identity primary key, entity_id bigint not null references public.categories(id) on delete cascade, locale_id bigint not null references public.locales(id) on delete cascade, name varchar(120) not null, description varchar(500) not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(entity_id, locale_id));
create table if not exists public.tag_translations (id bigint generated by default as identity primary key, entity_id bigint not null references public.tags(id) on delete cascade, locale_id bigint not null references public.locales(id) on delete cascade, name varchar(120) not null, description varchar(500) not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(entity_id, locale_id));
create table if not exists public.post_categories (post_id bigint not null references public.posts(id) on delete cascade, category_id bigint not null references public.categories(id) on delete cascade, primary key(post_id, category_id));
create table if not exists public.post_tags (post_id bigint not null references public.posts(id) on delete cascade, tag_id bigint not null references public.tags(id) on delete cascade, primary key(post_id, tag_id));
create index if not exists category_translations_locale_idx on public.category_translations(locale_id);
create index if not exists tag_translations_locale_idx on public.tag_translations(locale_id);
create index if not exists post_categories_category_idx on public.post_categories(category_id);
create index if not exists post_tags_tag_idx on public.post_tags(tag_id);
alter table public.categories enable row level security;
alter table public.tags enable row level security;
alter table public.category_translations enable row level security;
alter table public.tag_translations enable row level security;
alter table public.post_categories enable row level security;
alter table public.post_tags enable row level security;
revoke all on table public.categories, public.tags, public.category_translations, public.tag_translations, public.post_categories, public.post_tags from anon, authenticated;
